import React, { useState, useEffect } from 'react';

const CardReservation = () => {
  const [formData, setFormData] = useState({
    dateRetrait: '',
    heureRetrait: '10:00',
    dateRetour: '',
    heureRetour: '10:00',
    transmission: 'Manuelle',
    siege: '4',
    categorie: 'Berline',
    carburant: 'Diesel'
  });

  const [results, setResults] = useState([]);
  const [isSearching, setIsSearching] = useState(false);

  const mockCars = [
    { id: 1, modele: 'Peugeot 208', categorie: 'Compacte', prix: 120 },
    { id: 2, modele: 'Renault Clio', categorie: 'Compacte', prix: 110 },
    { id: 3, modele: 'VW Golf', categorie: 'Berline', prix: 150 },
    { id: 4, modele: 'Toyota RAV4', categorie: 'SUV', prix: 180 }
  ];

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setIsSearching(true);

    setTimeout(() => {
      const filteredCars = mockCars.filter(car => car.categorie === formData.categorie);
      setResults(filteredCars);
      setIsSearching(false);
      document.getElementById('results').scrollIntoView({ behavior: 'smooth' });
    }, 300);
  };

  useEffect(() => {
    const today = new Date().toISOString().split('T')[0];
    const defaultReturnDate = new Date();
    defaultReturnDate.setDate(defaultReturnDate.getDate() + 2);
    const defaultReturnDateStr = defaultReturnDate.toISOString().split('T')[0];

    setFormData(prev => ({
      ...prev,
      dateRetrait: today,
      dateRetour: defaultReturnDateStr
    }));
  }, []);

  return (
    <div className="max-w-5xl mx-auto mt-4 p-2 bg-white rounded-lg shadow-md">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
        {/* Formulaire */}
        <div className="bg-gray-50 p-3 rounded-lg">
          <h2 className="text-sm font-bold mb-2">Dates de location</h2>
          <div className="grid grid-cols-2 gap-2 text-xs mb-2">
            <div>
              <label className="block mb-0.5">Début*</label>
              <input
                type="date"
                name="dateRetrait"
                value={formData.dateRetrait}
                onChange={handleChange}
                className="w-full p-1 border rounded"
              />
            </div>
            <div>
              <label className="block mb-0.5">Heure*</label>
              <input
                type="time"
                name="heureRetrait"
                value={formData.heureRetrait}
                onChange={handleChange}
                className="w-full p-1 border rounded"
              />
            </div>
            <div>
              <label className="block mb-0.5">Fin*</label>
              <input
                type="date"
                name="dateRetour"
                value={formData.dateRetour}
                onChange={handleChange}
                className="w-full p-1 border rounded"
              />
            </div>
            <div>
              <label className="block mb-0.5">Heure*</label>
              <input
                type="time"
                name="heureRetour"
                value={formData.heureRetour}
                onChange={handleChange}
                className="w-full p-1 border rounded"
              />
            </div>
          </div>

          <h2 className="text-sm font-bold mb-2">Préférences</h2>
          <div className="grid grid-cols-2 gap-2 text-xs">
            <div>
              <label className="block mb-0.5">Catégorie</label>
              <select
                name="categorie"
                value={formData.categorie}
                onChange={handleChange}
                className="w-full p-1 border rounded"
              >
                <option value="Economique">Eco</option>
                <option value="Compacte">Compacte</option>
                <option value="Berline">Berline</option>
                <option value="SUV">SUV</option>
              </select>
            </div>
            <div>
              <label className="block mb-0.5">Sièges</label>
              <select
                name="siege"
                value={formData.siege}
                onChange={handleChange}
                className="w-full p-1 border rounded"
              >
                {[2, 4, 5, 7].map(num => (
                  <option key={num} value={num}>{num}</option>
                ))}
              </select>
            </div>
          </div>

          <button
            onClick={handleSubmit}
            className="w-full mt-3 p-2 bg-blue-600 text-white text-xs font-semibold rounded hover:bg-blue-700"
          >
            {isSearching ? 'Recherche en cours...' : 'Rechercher'}
          </button>
        </div>

        {/* Résultats */}
        <div id="results" className="bg-gray-50 p-3 rounded-lg">
          {isSearching ? (
            <div className="flex justify-center items-center h-full">
              <div className="animate-spin rounded-full h-6 w-6 border-t-2 border-b-2 border-blue-500"></div>
            </div>
          ) : results.length > 0 ? (
            <>
              <h2 className="text-sm font-bold mb-2">Résultats ({results.length})</h2>
              <div className="overflow-y-auto max-h-64 text-xs">
                {results.map(car => (
                  <div key={car.id} className="flex justify-between items-center p-2 border-b">
                    <div>
                      <div className="font-medium">{car.modele}</div>
                      <div className="text-gray-500">{car.categorie}</div>
                    </div>
                    <div className="text-right">
                      <div className="font-bold">{car.prix} €/j</div>
                      <button className="bg-green-500 text-white px-2 py-1 rounded text-xs hover:bg-green-600">
                        Réserver
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </>
          ) : (
            <div className="text-center text-gray-500 text-xs py-8">Aucun véhicule trouvé</div>
          )}
        </div>
      </div>
    </div>
  );
};

export default CardReservation;
